import pandas as pd
cols = ['league_id','date','home_team_goal','away_team_goal','home_team_api_id','away_team_api_id','match_api_id']
found = []
for chunk in pd.read_csv('csv/Match.csv', usecols=cols, chunksize=100000):
    # ensure date is string
    chunk['date'] = chunk['date'].astype(str)
    mask = (chunk['league_id']==1) & chunk['date'].str.startswith('2008-09-24')
    sel = chunk[mask]
    if not sel.empty:
        found.append(sel)
if found:
    res = pd.concat(found)
    for _, row in res.iterrows():
        print(row.to_dict())
else:
    print('NO_MATCH')

